public DEV_CleanupTaskSettings cleanupTaskSettings(boolean _forupdate = false)
{
    DEV_CleanupTaskSettings     record;

    record.selectForUpdate(_forupdate);

    if (this.CleanupTaskSettingsRecId)
    {
        select firstonly record
            where   record.RecId == this.CleanupTaskSettingsRecId;
    }

    return record;
}

public void querySetDefault()
{
    DEV_CleanupDataTaskBase cleanupClass = this.getCleanupClass();
    Query                   query;
    SysQueryRun             queryRun;
    container               packedCon;

    if (cleanupClass)
    {
        query = cleanupClass.getQuery();
        if (query)
        {
            queryRun = new SysQueryRun(query);
            packedCon = queryRun.pack();
        }
    }

    this.QueryPacked = packedCon;
    this.update();
}

public void queryChangeValue()
{
    DEV_CleanupDataTaskBase cleanupClass = this.getCleanupClass();
    Query                   query;
    SysQueryRun             queryRun;
    QueryRun                packedQueryRun;
    container               packedCon;
    boolean                 isUpdated;

    if (cleanupClass)
    {
        packedCon = this.QueryPacked;

        if (packedCon != conNull() && SysQuery::isPackedOk(packedCon))
        {
            packedQueryRun = new QueryRun(packedCon);
            query = packedQueryRun.query();
        }
        else
        {
            query = cleanupClass.getQuery();
        }

        if (query)
        {
            queryRun = new SysQueryRun(query);
            queryRun.saveUserSetup(false);
            queryRun.promptAllowQueryFilters(false);
            if (queryRun.prompt())
            {
                packedCon = queryRun.pack();
                isUpdated = true;
            }
        }
    }
    if (isUpdated)
    {
        this.QueryPacked = packedCon;
        this.update();
    }
}

public void updateHeaderSettings()
{
    DEV_CleanupTaskSettings         cleanupTaskSettings;
    DEV_CleanupTaskSettingsQuery    settingsQueryPeriodic;
    DEV_CleanupTaskSettingsQuery    settingsQueryToDate;
    TransDate                       datePeriodic, dateToDate;
    TransDate                       cleanupDate;

    ttsbegin;

    cleanupTaskSettings = this.cleanupTaskSettings(true);

    if (cleanupTaskSettings)
    {
        select minof(CleanupDays), minof(RecId) from settingsQueryPeriodic
            where   settingsQueryPeriodic.CleanupTaskSettingsRecId == cleanupTaskSettings.RecId
                    && settingsQueryPeriodic.CleanupDateType == DEV_CleanupDateType::Periodic;

        if (settingsQueryPeriodic.RecId)
        {
            datePeriodic = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()) - settingsQueryPeriodic.CleanupDays;
        }

        select minof(CleanupDate), minof(RecId) from settingsQueryToDate
            where   settingsQueryToDate.CleanupTaskSettingsRecId == cleanupTaskSettings.RecId
                    && settingsQueryToDate.CleanupDateType == DEV_CleanupDateType::ToDate;
        if (settingsQueryToDate.RecId)
        {
            dateToDate = settingsQueryToDate.CleanupDate;
        }

        if (datePeriodic || dateToDate)
        {
            if (datePeriodic && dateToDate)
            {
                cleanupDate = min(datePeriodic, dateToDate);

                if (cleanupDate == dateToDate)
                {
                    cleanupTaskSettings.CleanupDate = settingsQueryToDate.CleanupDate;
                    cleanupTaskSettings.CleanupDateType = DEV_CleanupDateType::ToDate;
                    cleanupTaskSettings.CleanupDays = 0;
                }
                else
                {
                    cleanupTaskSettings.CleanupDate = dateNull();
                    cleanupTaskSettings.CleanupDateType = DEV_CleanupDateType::Periodic;
                    cleanupTaskSettings.CleanupDays = settingsQueryPeriodic.CleanupDays;

                }
            }
            else if (dateToDate)
            {
                cleanupTaskSettings.CleanupDate = settingsQueryToDate.CleanupDate;
                cleanupTaskSettings.CleanupDateType = DEV_CleanupDateType::ToDate;
                cleanupTaskSettings.CleanupDays = 0;
            }
            else
            {
                cleanupTaskSettings.CleanupDate = dateNull();
                cleanupTaskSettings.CleanupDateType = DEV_CleanupDateType::Periodic;
                cleanupTaskSettings.CleanupDays = settingsQueryPeriodic.CleanupDays;
            }

            cleanupTaskSettings.update();
        }
    }

    ttscommit;
}

public void insert()
{
    ttsbegin;

    super();

    this.updateHeaderSettings();

    ttscommit;
}

public void update()
{
    ttsbegin;

    super();

    this.updateHeaderSettings();

    ttscommit;
}

public void delete()
{
    ttsbegin;

    super();

    this.updateHeaderSettings();

    ttscommit;
}

public Query getPackedQuery(DEV_CleanupDataTaskBase _caller)
{
    Query ret;

    container packedCon = this.QueryPacked;

    if (packedCon != conNull() && SysQuery::isPackedOk(packedCon))
    {
        QueryRun packedQueryRun = new QueryRun(packedCon);
        ret = packedQueryRun.query();
    }
    else if (_caller)
    {
        ret = _caller.getQuery();
    }

    return ret;
}

[SysClientCacheDataMethodAttribute(true)]
display Notes getPackedQueryText()
{
    Query       query = this.getPackedQuery(null);

    if (!query)
    {
        DEV_CleanupDataTaskBase cleanupClass = this.getCleanupClass();

        if (cleanupClass)
        {
            query = cleanupClass.getQuery();
        }
    }

    return query ? query.dataSourceNo(1).toString() : '';
}

public void initFromCleanupTaskSettings(DEV_CleanupTaskSettings _cleanupTaskSettings)
{
    this.CleanupTaskSettingsRecId   = _cleanupTaskSettings.RecId;
    this.CleanupDateType            = _cleanupTaskSettings.CleanupDateType;
    this.CleanupDays                = _cleanupTaskSettings.CleanupDays;
    this.CleanupDate                = _cleanupTaskSettings.CleanupDate;
}
